const input = $input.first().json;

const schema = (input.wa_phone_id || 'clinica-demo')
  .replace(/-/g, '_')
  .replace(/[^a-zA-Z0-9_]/g, '')
  .toLowerCase();

const numero = input.numero;

// Construir SET dinámico solo con campos que tengan valor real
const updates = [];

if (input.nombre && input.nombre !== 'null' && input.nombre !== '') 
  updates.push(`nombre = '${input.nombre.replace(/'/g, "''")}'`);

if (input.tratamiento_interes && input.tratamiento_interes !== 'null' && input.tratamiento_interes !== '') 
  updates.push(`tratamiento_interes = '${input.tratamiento_interes.replace(/'/g, "''")}'`);

if (input.urgencia && input.urgencia !== 'null' && input.urgencia !== '') 
  updates.push(`urgencia = '${input.urgencia.replace(/'/g, "''")}'`);

if (input.disponibilidad && input.disponibilidad !== 'null' && input.disponibilidad !== '') 
  updates.push(`disponibilidad = '${input.disponibilidad.replace(/'/g, "''")}'`);

if (input.email && input.email !== 'null' && input.email !== '') 
  updates.push(`email = '${input.email.replace(/'/g, "''")}'`);

if (input.estado && input.estado !== 'null' && input.estado !== '') 
  updates.push(`estado = '${input.estado}'`);

if (input.presupuesto && input.presupuesto !== 'null' && input.presupuesto !== '') 
  updates.push(`presupuesto = '${input.presupuesto.replace(/'/g, "''")}'`);

// Siempre actualizar ultima_interaccion y calificado si hay datos
updates.push(`ultima_interaccion = '${new Date().toISOString()}'`);

if (updates.length > 1) {
  updates.push(`calificado = TRUE`);
}

const query = `UPDATE ${schema}.conversaciones SET ${updates.join(', ')} WHERE numero = '${numero}' RETURNING *;`;

return [{ json: { query } }];

